{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C52"],
      "claim": "Absolute bioavailability of the 1500 mg GSK1322322 tablet was 77% after a meal in healthy volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Linezolid administered at an oral dose of 375 mg demonstrated an absolute bioavailability of 100% in patients, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Apalutamide had an absolute bioavailability of approximately 100% in a human mass balance study, well above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All threshold-relevant numeric evidence from the supplied molecules supports F >= 20%, with absolute human bioavailability values ranging from about 20-25% to approximately 100%; therefore the prediction is high.",
  "evidence_gaps": [
    "Molecule 8 (venadaparib) provides only qualitative 'good' bioavailability without a numeric F value, so it is not threshold-relevant.",
    "Molecule 1 includes a record (C25) attributed to brigatinib under the same molecule grouping; this provenance conflict was discounted.",
    "Molecule 4 includes a record (C54) for 9-hydroxyrisperidone rather than paliperidone; this inconsistent card was discounted. Paliperidone bioavailability is formulation-dependent, but the relevant values are above the threshold.",
    "Molecule 3 (encainide) has a wide reported bioavailability range and some qualitative low reports, but its strongest ordinary-condition absolute value is above the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

